@Allow.PerformancePlan.release_requires_reaping : ∀ {s t : Allow.PerformancePlan.Worker},
  Allow.PerformancePlan.Step s t →
    Eq.{1} t.phase Allow.PerformancePlan.Phase.vacant → Eq.{1} s.phase Allow.PerformancePlan.Phase.reaped

@Allow.PerformancePlan.poison_prevents_delivery_in_generation : ∀ {s t : Allow.PerformancePlan.Worker},
  Allow.PerformancePlan.Step s t →
    Eq.{1} s.poisoned true → Eq.{1} t.generation s.generation → Eq.{1} t.delivered s.delivered

@Allow.PerformancePlan.poisoned_trace_cannot_deliver : ∀ {s t : Allow.PerformancePlan.Worker},
  Allow.PerformancePlan.Trace s t →
    Eq.{1} s.poisoned true → Eq.{1} t.generation s.generation → Eq.{1} t.poisoned true ∧ Eq.{1} t.delivered s.delivered

@Allow.PerformancePlan.delivered_reply_is_guarded_step : ∀ {s t : Allow.PerformancePlan.Worker}
  {responseGeneration : Nat},
  Eq.{1} (Allow.PerformancePlan.deliverReply s responseGeneration) (some.{0} t) → Allow.PerformancePlan.Step s t

@Allow.PerformancePlan.database_release_requires_observation : ∀ {s t : Allow.PerformancePlan.DatabaseLease}
  {owner : Nat},
  Eq.{1} (Allow.PerformancePlan.releaseDatabase s owner) (some.{0} t) →
    Eq.{1} s.phase Allow.PerformancePlan.DatabasePhase.terminated ∧ Eq.{1} owner s.ownerGeneration

@Allow.PerformancePlan.every_accepted_run_meets_target : ∀ {runs : List.{0} Allow.PerformancePlan.Run}
  {r : Allow.PerformancePlan.Run},
  Allow.PerformancePlan.SeriesPass runs → Membership.mem.{0, 0} runs r → LT.lt.{0} r.p95Micros 300000

@Allow.PerformancePlan.observed_slow_run_rejects_series : ∀ {runs : List.{0} Allow.PerformancePlan.Run}
  {r : Allow.PerformancePlan.Run},
  Membership.mem.{0, 0} runs r → LE.le.{0} 300000 r.p95Micros → ¬Allow.PerformancePlan.SeriesPass runs

