  (List.cons.{0} { p95Micros := 200000, failures := 0, measured := 1000, warmups := 100, profileMatches := true }
    (List.cons.{0} { p95Micros := 210000, failures := 0, measured := 1000, warmups := 100, profileMatches := true }
      (List.cons.{0} { p95Micros := 220000, failures := 0, measured := 1000, warmups := 100, profileMatches := true }
        List.nil.{0})))
